\begin{ex}%[8H9V6]
\immini[thm]{
Cho tam giác ${A B C }$ vuông tại ${A }$ $(A B  < A C )$, có đường cao $A H $ $(H  \in B C )$.

 a) Chứng minh $\triangle {H B A } \backsim \triangle {A B C }$.

b) Kẻ ${B D }$ là đường phân giác của tam giác ${A B C }$. Giả sử ${A B }={13}$ cm, $A C =84$ cm. Tính độ dài các đoạn thẳng ${B C },{D A },{D C }$.

c) Gọi ${K }$ là giao điểm của ${A H }$ và ${B D }$. Chứng minh: $A K =A D $.
}{
\begin{tikzpicture}[line join = round, line cap=round,>=stealth,font=\footnotesize,scale=1]
                \path 
                (0,0) coordinate (A)
                (4,0) coordinate (C)
                (0,3) coordinate (B)    
                ($(B)!(A)!(C)$) coordinate (H)           
                ($(B)!1cm!(A)$) coordinate (A1)
                ($(B)!1cm!(C)$) coordinate (C1)
                ($(A1)!0.5!(C1)$) coordinate (Bt)
                (intersection of B--Bt and A--C) coordinate (D) 
                (intersection of B--D and A--H) coordinate (I)  ;   
                \draw (B)--(A)--(C)--cycle (B)--(D) (A)--(H)        
                ;

                \draw pic[draw, angle radius=3mm, angle eccentricity=1.2]{right angle = B--A--C};
                \draw pic[draw, angle radius=3mm, angle eccentricity=1.2]{right angle = A--H--C};
                \draw pic[draw, angle radius=5mm, angle eccentricity=1.2]{angle = A--B--C};
                \path 
                (A)--(B)node[left,pos=0.5,scale=1.2]{$13$}
                (C)--(A)node[below,pos=0.5,scale=1.2]{$84$}              
                ;       
                   \filldraw[black] (A) circle (2pt) node[below left] {$A $};
    \filldraw[black] (B) circle (2pt) node[above left] {$B $};
    \filldraw[black] (C) circle (2pt) node[below right] {$C $};
   \filldraw[black] (D) circle (2pt) node[below left]{$D $};
    \filldraw[black] (H) circle (2pt) node[above right] {$H $};
    \filldraw[black] (I) circle (2pt) node[above left] {$K $};
            \end{tikzpicture}
}
\loigiai{
a) Xét $\triangle {H B A }$ và $\triangle {A B C }$ có\\
$\widehat{A H B  }= \widehat{B A C } =90^\circ$\\
$\widehat{A B H }$ chung.\\
Vậy $\triangle {H B A } \backsim \triangle {A B C }$ (g.g).\\
b) $\triangle A B C $ vuông tại ${A }$, theo Pytagores ta có\\
$B C ^{2}=A B ^{2}+A C ^{2} \Rightarrow B C  =85$.\\
Ta có $B D $ là đường phân giác của $\triangle A B C $.\\
$\dfrac{D A }{D C }=\dfrac{B A }{B C }\Rightarrow \dfrac{D A }{13}=\dfrac{D C }{85}=\dfrac{D A +D C }{98}=\dfrac{84}{98}=\dfrac{6}{7}$ (dãy tỉ số bằng nhau)\\
$\Rightarrow D A =\dfrac{78}{7}cm;D C =\dfrac{510}{7}cm $.\\
c) Ta có $\widehat{A D K }+\widehat{A B D }=90^{\circ}$ ($\triangle A B D $ vuông tại ${A }$).(1)\\
$\widehat{A K D }=\widehat{B K H }$ (đối đỉnh) và $\widehat{B K H }+\widehat{C B D }=90^{\circ}$.\\
Nên $\widehat{A K D }+\widehat{C B D }=90^{\circ}$. (2)\\
Từ (1)(2) và $\widehat{A B D }=\widehat{C B D }$ ($B D $ phân giác $\widehat{A B C }$).\\
Suy ra $\widehat{A K D }=\widehat{A D K }$ hay $\triangle{ A K D }$ cân tại ${A }$.\\
Suy ra $A K =A D $.
}\end{ex}

\begin{ex}%[8H9V6]
\immini[thm]{
Cho tam giác ${MNP}$ vuông tại ${M}$ $(MN < MP)$, có đường cao $ME$ $(E \in NP)$.

 a) Chứng minh $\triangle {ENM} \backsim \triangle {MNP}$.

b) Kẻ ${NQ}$ là đường phân giác của tam giác ${MNP}$. Giả sử ${MN}={48}$ cm, $MP=55$ cm. Tính độ dài các đoạn thẳng ${NP},{QM},{QP}$.

c) Gọi ${F}$ là giao điểm của ${ME}$ và ${NQ}$. Chứng minh: $MF=MQ$.
}{
\begin{tikzpicture}[line join = round, line cap=round,>=stealth,font=\footnotesize,scale=1]
                \path 
                (0,0) coordinate (A)
                (4,0) coordinate (C)
                (0,3) coordinate (B)    
                ($(B)!(A)!(C)$) coordinate (H)           
                ($(B)!1cm!(A)$) coordinate (A1)
                ($(B)!1cm!(C)$) coordinate (C1)
                ($(A1)!0.5!(C1)$) coordinate (Bt)
                (intersection of B--Bt and A--C) coordinate (D) 
                (intersection of B--D and A--H) coordinate (I)  ;   
                \draw (B)--(A)--(C)--cycle (B)--(D) (A)--(H)        
                ;

                \draw pic[draw, angle radius=3mm, angle eccentricity=1.2]{right angle = B--A--C};
                \draw pic[draw, angle radius=3mm, angle eccentricity=1.2]{right angle = A--H--C};
                \draw pic[draw, angle radius=5mm, angle eccentricity=1.2]{angle = A--B--C};
                \path 
                (A)--(B)node[left,pos=0.5,scale=1.2]{$48$}
                (C)--(A)node[below,pos=0.5,scale=1.2]{$55$}              
                ;       
                   \filldraw[black] (A) circle (2pt) node[below left] {$M$};
    \filldraw[black] (B) circle (2pt) node[above left] {$N$};
    \filldraw[black] (C) circle (2pt) node[below right] {$P$};
   \filldraw[black] (D) circle (2pt) node[below left]{$Q$};
    \filldraw[black] (H) circle (2pt) node[above right] {$E$};
    \filldraw[black] (I) circle (2pt) node[above left] {$F$};
            \end{tikzpicture}
}
\loigiai{
a) Xét $\triangle {ENM}$ và $\triangle {MNP}$ có\\
$\widehat{MEN }= \widehat{NMP} =90^\circ$\\
$\widehat{MNE}$ chung.\\
Vậy $\triangle {ENM} \backsim \triangle {MNP}$ (g.g).\\
b) $\triangle MNP$ vuông tại ${M}$, theo Pytagores ta có\\
$NP^{2}=MN^{2}+MP^{2} \Rightarrow NP =73$.\\
Ta có $NQ$ là đường phân giác của $\triangle MNP$.\\
$\dfrac{QM}{QP}=\dfrac{NM}{NP}\Rightarrow \dfrac{QM}{48}=\dfrac{QP}{73}=\dfrac{QM+QP}{121}=\dfrac{55}{121}=\dfrac{5}{11}$ (dãy tỉ số bằng nhau)\\
$\Rightarrow QM=\dfrac{240}{11}cm;QP=\dfrac{365}{11}cm $.\\
c) Ta có $\widehat{MQF}+\widehat{MNQ}=90^{\circ}$ ($\triangle MNQ$ vuông tại ${M}$).(1)\\
$\widehat{MFQ}=\widehat{NFE}$ (đối đỉnh) và $\widehat{NFE}+\widehat{PNQ}=90^{\circ}$.\\
Nên $\widehat{MFQ}+\widehat{PNQ}=90^{\circ}$. (2)\\
Từ (1)(2) và $\widehat{MNQ}=\widehat{PNQ}$ ($NQ$ phân giác $\widehat{MNP}$).\\
Suy ra $\widehat{MFQ}=\widehat{MQF}$ hay $\triangle{ MFQ}$ cân tại ${M}$.\\
Suy ra $MF=MQ$.
}\end{ex}

